"use client";
import React, { useState, useEffect, useCallback } from 'react';
import './generate.css';
import { clearStoredSetting, useStoredSetting } from '@/lib/useStoredSetting';
import { useFeeSettings } from '@/lib/useFeeSettings';
import { useFeatures } from '@/lib/useFeatures';
import ChallanBill from '../components/ChallanBill';
import FeeSettingsFields from '../components/FeeSettingsFields';
import { COMMON_CHARGES, VoucherCharges } from '../components/ChargesEditor';
import type { FeeVoucher, RecordId, SchoolClass } from '@/lib/types';
import { yearOptions } from '@/lib/fees';

async function fetchFeesFor(month: string, year: string): Promise<FeeVoucher[]> {
  const res = await fetch(`/api/fees?month=${month}&year=${year}`, { cache: 'no-store' });
  const data = await res.json();
  return Array.isArray(data) ? data : [];
}

async function fetchClassList(): Promise<SchoolClass[]> {
  const res = await fetch('/api/classes');
  const data = await res.json();
  return Array.isArray(data) ? data : [];
}

export default function GenerateFees() {
  const [fees, setFees] = useState<FeeVoucher[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [schoolName, setSchoolName] = useStoredSetting('fms-school-name', 'YOUR SCHOOL NAME');
  const [schoolAddress, setSchoolAddress] = useStoredSetting('fms-school-address', 'Rawalpindi, Pakistan');
  const [logo, setLogo] = useStoredSetting('fms-school-logo', '');
  const [printTargetId, setPrintTargetId] = useState<RecordId | null>(null);

  // Professional Branding States (saved in this browser)
  const [bankName, setBankName] = useStoredSetting('fms-bank-name', 'Meezan Bank Limited');
  const [bankBranch, setBankBranch] = useStoredSetting('fms-bank-branch', 'Bank Road Sadar, Rawalpindi');
  const [bankAccountTitle, setBankAccountTitle] = useStoredSetting('fms-bank-title', 'YOUR SCHOOL SYSTEM');
  const [bankAccountNo, setBankAccountNo] = useStoredSetting('fms-bank-no', '0000-000000-0000');
  const [instituteId, setInstituteId] = useStoredSetting('fms-inst-id', '2109');
  const [paymentMethods, setPaymentMethods] = useStoredSetting('fms-pay-methods', '1. CASH DEPOSIT AT ALL BRANCHES OF MENTIONED BANK.\n2. ONLINE VIA MOBILE BANKING OR ATM.');
  const [challanNote, setChallanNote] = useStoredSetting('fms-note', 'Fine is imposed to maintain discipline. Amount of fine is donated as charity.');
  // Due days and late fine are school-wide (the server charges the fine), not per browser.
  const { settings: feeSettings, save: saveFeeSettings, canEdit: canEditFees } = useFeeSettings();
  const [showConfig, setShowConfig] = useState(false);
  const { has } = useFeatures();

  const handlePrintIndividual = (id: RecordId) => {
    setPrintTargetId(id);
    setTimeout(() => {
      window.print();
    }, 100);
  };

  const currentMonth = new Date().toLocaleString('default', { month: 'long' });
  const currentYear = new Date().getFullYear().toString();

  const fetchMonthFees = useCallback(
    (m: string = currentMonth, y: string = currentYear) =>
      fetchFeesFor(m, y).then(setFees).catch((err) => console.error("Failed to fetch vouchers", err)),
    [currentMonth, currentYear]
  );

  const [classes, setClasses] = useState<SchoolClass[]>([]);

  const [genMonth, setGenMonth] = useState(currentMonth);
  const [genYear, setGenYear] = useState(currentYear);
  const [isGenerating, setIsGenerating] = useState(false);

  // Charges on top of the fee: one voucher's (modal), or one charge for every voucher shown.
  const [chargesFor, setChargesFor] = useState<FeeVoucher | null>(null);
  const [showBulkCharge, setShowBulkCharge] = useState(false);
  const [bulkLabel, setBulkLabel] = useState('');
  const [bulkAmount, setBulkAmount] = useState('');
  const [addingCharge, setAddingCharge] = useState(false);

  useEffect(() => {
    // Inject dynamic @page style for A4 landscape
    const styleEl = document.createElement('style');
    styleEl.id = 'print-page-style-landscape';
    styleEl.innerHTML = `@media print { @page { size: A4 landscape !important; margin: 5mm !important; } }`;
    document.head.appendChild(styleEl);

    return () => {
      const el = document.getElementById('print-page-style-landscape');
      if (el) el.remove();
    };
  }, []);

  useEffect(() => {
    fetchMonthFees();
    fetchClassList().then(setClasses).catch(() => console.error("Failed to fetch classes"));
  }, [fetchMonthFees]);

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        if (!setLogo(ev.target?.result as string)) {
          alert('Image too large for local storage! Please select a smaller logo (under 2MB).');
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const [selectedClass, setSelectedClass] = useState('all');

  const filteredFees = (fees || []).filter(f => {
    const matchesSearch = (f.studentName || "").toLowerCase().includes(searchQuery.toLowerCase()) || 
                         (f.fatherName || "").toLowerCase().includes(searchQuery.toLowerCase()) ||
                         (f.id || "").toString() === searchQuery;

    // Flexible class match (trimming both sides)
    const matchesClass = selectedClass === 'all' || 
                         (f.className || "").toString().trim() === selectedClass.trim();
    return matchesSearch && matchesClass;
  });

  const handlePrintBulk = async () => {
    if (filteredFees.length === 0) {
      const confirmGen = confirm("No vouchers found for this month/class. Do you want to generate them now?");
      if (!confirmGen) return;

      setIsGenerating(true);
      try {
        const res = await fetch('/api/fees', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ month: genMonth, year: genYear, classId: classes.find(c => c.name === selectedClass)?.id || 'all' })
        });
        if (res.ok) {
          await fetchMonthFees(genMonth, genYear);
          // Small delay to allow state to update before printing
          setTimeout(() => {
            setPrintTargetId(-1);
            setTimeout(() => window.print(), 300);
          }, 500);
        }
      } finally {
        setIsGenerating(false);
      }
      return;
    }

    setPrintTargetId(-1);
    setTimeout(() => {
      window.print();
    }, 200);
  };

  const handleBulkCharge = async (e: React.FormEvent) => {
    e.preventDefault();
    const label = bulkLabel.trim();
    const amount = parseFloat(bulkAmount) || 0;
    if (!confirm(`Add ${label} of Rs. ${amount} to all ${filteredFees.length} voucher(s) shown? Vouchers that already have a "${label}" charge are left as they are.`)) return;
    setAddingCharge(true);
    try {
      const res = await fetch('/api/fees', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ids: filteredFees.map((f) => f.id), charge: { label, amount } })
      });
      const data = await res.json().catch(() => null);
      if (!res.ok) {
        alert(data?.error || 'Failed to add the charge.');
        return;
      }
      alert(`${label} added to ${data.added} voucher(s).${data.skipped ? ` ${data.skipped} skipped (already had it, or too old to change).` : ''}`);
      setShowBulkCharge(false);
      setBulkLabel('');
      setBulkAmount('');
      fetchMonthFees(genMonth, genYear);
    } finally {
      setAddingCharge(false);
    }
  };


  return (
    <div style={{animation: 'fadeIn 0.5s ease-out'}}>
      <div className="no-print" style={{display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: '2rem', gap: '1.5rem', background: 'var(--bg-card)', padding: '1.5rem', borderRadius: '12px', border: '1px solid var(--border)'}}>
        <div style={{flex: 1, display: 'flex', gap: '1rem'}}>
          <div>
            <label className="form-label">Billing Month</label>
            <select className="form-input" value={genMonth} onChange={e => {setGenMonth(e.target.value); fetchMonthFees(e.target.value, genYear);}}>
              {["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"].map(m => <option key={m} value={m}>{m}</option>)}
            </select>
          </div>
          <div>
            <label className="form-label">Year</label>
            <select className="form-input" value={genYear} onChange={e => {setGenYear(e.target.value); fetchMonthFees(genMonth, e.target.value);}}>
              {yearOptions().map(y => <option key={y} value={y}>{y}</option>)}
            </select>
          </div>
          <div style={{flex: 1}}>
            <label className="form-label">Filter Class</label>
            <select className="form-input" value={selectedClass} onChange={e => setSelectedClass(e.target.value)}>
              <option value="all">All Classes</option>
              {classes.map(c => {
                const displayName = `${c.name}${c.section ? ` - ${c.section}` : ''}`;
                return <option key={c.id} value={displayName}>{displayName}</option>;
              })}
            </select>
          </div>
        </div>

        <div style={{display: 'flex', gap: '1rem', alignItems: 'center'}}>
          <button 
            className="btn btn-primary" 
            style={{height: '42px', padding: '0 1.5rem', fontWeight: 800, fontSize: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem'}}
            onClick={handlePrintBulk}
            disabled={isGenerating}
          >
            <span>🖨️</span> {isGenerating ? 'Processing...' : `Print Class Challans (${filteredFees.length})`}
          </button>
          <input 
            type="text" 
            placeholder="Search student..." 
            className="form-input" 
            style={{maxWidth: '250px', height: '42px'}}
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </div>

      {filteredFees.length === 0 ? (
        <div className="glass-panel no-print" style={{padding: '4rem', textAlign: 'center'}}>
          <h3 style={{color: 'var(--text-muted)'}}>{fees.length > 0 ? "No vouchers match your filters." : "No vouchers generated for this billing cycle yet."}</h3>
        </div>
      ) : (
        <>
          <div className="no-print" style={{marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '1rem', background: 'var(--bg-card)', padding: '1rem', borderRadius: '8px', border: '1px solid var(--border)'}}>
            <div style={{flex: 1, display: 'flex', alignItems: 'center', gap: '1rem'}}>
               <strong style={{color: 'var(--text-main)', whiteSpace: 'nowrap'}}>Challan Branding:</strong>
               <input 
                 type="text" 
                 placeholder="School Name" 
                 className="form-input" 
                 style={{height: '35px', fontSize: '0.85rem', maxWidth: '200px'}}
                 value={schoolName}
                 onChange={e => setSchoolName(e.target.value)}
               />
               <input 
                 type="text" 
                 placeholder="Location / Contact" 
                 className="form-input" 
                 style={{height: '35px', fontSize: '0.85rem'}}
                 value={schoolAddress}
                 onChange={e => setSchoolAddress(e.target.value)}
               />
            </div>
            <div style={{width: '1px', height: '25px', background: 'var(--border)'}}></div>
            <strong style={{color: 'var(--text-main)', whiteSpace: 'nowrap'}}>Logo:</strong>
            <input type="file" accept="image/*" onChange={handleLogoUpload} style={{fontSize: '0.8rem'}} />
            {logo && <button className="btn btn-secondary" onClick={() => clearStoredSetting('fms-school-logo')} style={{padding: '0.4rem'}}>Remove</button>}

            {has('charges') && (
              <button className="btn btn-secondary" onClick={() => setShowBulkCharge(!showBulkCharge)} style={{padding: '0.4rem 1rem'}}>
                 + Charge for all shown
              </button>
            )}
            <button className="btn btn-secondary" onClick={() => setShowConfig(!showConfig)} style={{padding: '0.4rem 1rem', marginLeft: has('charges') ? undefined : 'auto'}}>
               ⚙️ Challan Config
            </button>
          </div>

          {showBulkCharge && has('charges') && (
            <form onSubmit={handleBulkCharge} className="glass-panel no-print" style={{padding: '1.25rem', marginBottom: '1.5rem', display: 'flex', gap: '1rem', alignItems: 'flex-end', flexWrap: 'wrap'}}>
              <div style={{flex: '2 1 200px'}}>
                <label className="form-label">Charge (e.g. Examination Fee)</label>
                <input required className="form-input" list="bulk-charge-names" value={bulkLabel} onChange={e => setBulkLabel(e.target.value)} />
                <datalist id="bulk-charge-names">
                  {COMMON_CHARGES.map((name) => <option key={name} value={name} />)}
                </datalist>
              </div>
              <div style={{flex: '1 1 120px'}}>
                <label className="form-label">Amount (Rs.)</label>
                <input required type="number" min="1" className="form-input" value={bulkAmount} onChange={e => setBulkAmount(e.target.value)} />
              </div>
              <button type="submit" className="btn btn-primary" disabled={addingCharge || filteredFees.length === 0} style={{height: '42px'}}>
                {addingCharge ? 'Adding...' : `Add to ${filteredFees.length} voucher(s)`}
              </button>
              <p style={{flexBasis: '100%', margin: 0, fontSize: '0.85rem', color: 'var(--text-muted)'}}>
                Goes on every voucher in the list below ({genMonth} {genYear}{selectedClass !== 'all' ? `, ${selectedClass}` : ', all classes'}{searchQuery ? ', matching the search' : ''}). It is added to what each student owes and shows on the challan.
              </p>
            </form>
          )}

          {showConfig && (
            <div className="glass-panel no-print" style={{padding: '2rem', marginBottom: '1.5rem', display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '2rem', background: 'rgba(255,255,255,0.02)', border: '1px solid var(--border)', backdropFilter: 'blur(10px)'}}>
               <div>
                  <label className="form-label" style={{fontSize: '0.8rem', color: 'var(--primary)', marginBottom: '0.8rem'}}>BANK NAME</label>
                  <input className="form-input" value={bankName} onChange={e => setBankName(e.target.value)} style={{background: 'var(--bg-card)', border: '1px solid var(--border)', height: '50px', fontSize: '1rem'}} />
               </div>
               <div>
                  <label className="form-label" style={{fontSize: '0.8rem', color: 'var(--primary)', marginBottom: '0.8rem'}}>BANK BRANCH / ADDRESS</label>
                  <input className="form-input" value={bankBranch} onChange={e => setBankBranch(e.target.value)} style={{background: 'var(--bg-card)', border: '1px solid var(--border)', height: '50px', fontSize: '1rem'}} />
               </div>
               <div>
                  <label className="form-label" style={{fontSize: '0.8rem', color: 'var(--primary)', marginBottom: '0.8rem'}}>ACCOUNT TITLE</label>
                  <input className="form-input" value={bankAccountTitle} onChange={e => setBankAccountTitle(e.target.value)} style={{background: 'var(--bg-card)', border: '1px solid var(--border)', height: '50px', fontSize: '1rem'}} />
               </div>
               <div>
                  <label className="form-label" style={{fontSize: '0.8rem', color: 'var(--primary)', marginBottom: '0.8rem'}}>ACCOUNT NUMBER</label>
                  <input className="form-input" value={bankAccountNo} onChange={e => setBankAccountNo(e.target.value)} style={{background: 'var(--bg-card)', border: '1px solid var(--border)', height: '50px', fontSize: '1rem'}} />
               </div>
               <div style={{display: 'flex', gap: '1.5rem'}}>
                  <div style={{flex: 1.5}}>
                    <label className="form-label" style={{fontSize: '0.8rem', color: 'var(--primary)', marginBottom: '0.8rem'}}>INSTITUTE ID</label>
                    <input className="form-input" value={instituteId} onChange={e => setInstituteId(e.target.value)} style={{background: 'var(--bg-card)', border: '1px solid var(--border)', height: '50px', fontSize: '1rem'}} />
                  </div>
                  <FeeSettingsFields settings={feeSettings} canEdit={canEditFees} onSave={saveFeeSettings} inputStyle={{background: 'var(--bg-card)', border: '1px solid var(--border)', height: '50px', fontSize: '1rem'}} />
               </div>
               <div style={{gridColumn: '1 / -1'}}>
                  <label className="form-label" style={{fontSize: '0.7rem', color: 'var(--primary)'}}>PAYMENT METHODS (ONE PER LINE)</label>
                  <textarea className="form-input" rows={3} value={paymentMethods} onChange={e => setPaymentMethods(e.target.value)} style={{background: 'var(--bg-card)', border: '1px solid var(--border)', fontSize: '0.8rem'}} />
               </div>
               <div style={{gridColumn: '1 / -1'}}>
                  <label className="form-label" style={{fontSize: '0.7rem', color: 'var(--primary)'}}>CHALLAN FOOTER NOTE</label>
                  <input className="form-input" value={challanNote} onChange={e => setChallanNote(e.target.value)} style={{background: 'var(--bg-card)', border: '1px solid var(--border)', fontSize: '0.85rem'}} />
               </div>
            </div>
          )}

          <div className="glass-panel table-container no-print">
            <table className="table">
              <thead>
                <tr>
                  <th style={{width: '80px'}}>Sr No</th>
                  <th>Adm No</th>
                  <th>Student & Father Name</th>
                  <th>Class</th>
                  <th>Month</th>
                  <th>Monthly Fee</th>
                  <th>Arrears</th>
                  <th>Total Pending</th>
                  <th>Status</th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {filteredFees.map((f, idx) => (
                  <tr key={f.id}>
                    <td style={{color: 'var(--text-muted)'}}>#{idx + 1}</td>
                    <td style={{fontWeight: 700}}>{f.admissionNumber || 'N/A'}</td>
                    <td>
                      <div style={{fontWeight: 'bold'}}>{f.studentName}</div>
                      <div style={{fontSize: '0.8rem', color: 'var(--text-muted)'}}>S/O: {f.fatherName}</div>
                    </td>
                    <td style={{fontSize: '0.85rem'}}>{f.className}</td>
                    <td>{f.month} {f.year}</td>
                    <td>
                      Rs. {f.amount}
                      {(f.charges ?? []).length > 0 && (
                        <div style={{fontSize: '0.75rem', color: 'var(--text-muted)'}}>incl. {(f.charges ?? []).map((c) => `${c.label} ${c.amount}`).join(', ')}</div>
                      )}
                    </td>
                    <td style={{color: '#64748b'}}>Rs. {f.previousArrears || 0}</td>
                    <td style={{fontWeight: 700, color: '#e11d48'}}>
                      Rs. {f.balanceDue ?? 0}
                    </td>
                    <td><span className={`badge ${f.status === 'Paid' ? 'badge-success' : f.status === 'Partially Paid' ? 'badge-warning' : 'badge-danger'}`} style={{fontSize: '0.75rem'}}>{f.status}</span></td>
                    <td>
                      <div style={{display: 'flex', flexWrap: 'wrap', gap: '0.4rem', minWidth: '150px'}}>
                        <button 
                           className="btn btn-primary" 
                           style={{padding: '0.3rem 0.8rem', fontSize: '0.8rem'}}
                           onClick={() => handlePrintIndividual(f.id)}
                        >
                           Print
                        </button>
                        {has('charges') && (
                          <button
                             className="btn btn-secondary"
                             style={{padding: '0.3rem 0.8rem', fontSize: '0.8rem'}}
                             onClick={() => setChargesFor(f)}
                          >
                             Charges
                          </button>
                        )}
                        <button
                           className="btn"
                           style={{padding: '0.3rem 0.8rem', fontSize: '0.8rem', background: '#e11d48', color: 'white', border: 'none'}}
                           onClick={async () => {
                             if(confirm(`Are you sure you want to REVERSE voucher #${f.id} for ${f.studentName}? This will undo any payment.`)) {
                               const res = await fetch(`/api/fees?id=${f.id}`, { method: 'DELETE' });
                               if(res.ok) {
                                 alert('Fee reversed successfully.');
                                 fetchMonthFees(genMonth, genYear);
                               } else {
                                 alert((await res.json().catch(() => null))?.error || 'Failed to reverse fee.');
                               }
                             }
                           }}
                        >
                           Reverse
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {chargesFor && (
            <div className="no-print" style={{position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, background: 'rgba(0,0,0,0.8)', zIndex: 100, display: 'flex', alignItems: 'center', justifyContent: 'center', backdropFilter: 'blur(4px)'}}>
              <div className="glass-panel" style={{width: '100%', maxWidth: '480px', padding: '2rem', maxHeight: '90vh', overflowY: 'auto'}}>
                <h2 style={{marginBottom: '0.25rem'}}>Charges on voucher #{chargesFor.id}</h2>
                <p style={{marginBottom: '1.25rem'}}>{chargesFor.studentName}, {chargesFor.month} {chargesFor.year}. Added on top of the monthly fee (admission fee, exam fee...).</p>
                <VoucherCharges
                  voucher={chargesFor}
                  onCancel={() => setChargesFor(null)}
                  onSaved={() => { setChargesFor(null); fetchMonthFees(genMonth, genYear); }}
                />
              </div>
            </div>
          )}

          <div className="print-container print-only">
            {(printTargetId === -1 ? filteredFees : (printTargetId ? filteredFees.filter(f => f.id?.toString() === printTargetId?.toString()) : [])).map(f => {
              return (
                <div key={f.id} className="voucher-card">
                  {['Bank Copy', 'Student Copy', 'Information'].map((section, sectionIdx) => (
                    <div key={section} className="voucher-copy" style={{
                      borderRight: sectionIdx < 2 ? '1px solid #000' : 'none',
                    }}>
                      {/* eslint-disable-next-line @next/next/no-img-element -- logo is a data URL saved in this browser; next/image can't optimise it */}
                      {logo && <img src={logo} alt="Watermark" className="logo-watermark" />}
                      <div className="voucher-content">
                         {sectionIdx < 2 ? (
                           <>
                             {/* Header */}
                             <div className="copy-header">{section}</div>
                             <div style={{textAlign: 'center', marginBottom: '2mm'}}>
                                <h4 style={{margin: 0, fontSize: '10pt'}}>{bankName}</h4>
                                <p style={{margin: 0, fontSize: '7pt'}}>{bankBranch}</p>
                                <p style={{margin: '0.5mm 0', fontSize: '7pt', fontWeight: 700}}>( {bankAccountNo} )</p>
                             </div>

                             <div style={{border: '1px solid #000', padding: '1mm', fontSize: '8pt', marginBottom: '2mm', textAlign: 'center'}}>
                                <strong>A/C Title: {bankAccountTitle}</strong>
                             </div>

                             {/* Info Grid */}
                             <div className="info-grid">
                                <div className="info-item"><strong>Document No</strong> <span>{f.id}</span></div>
                                <div className="info-item"><strong>Date</strong> <span>{new Date().toLocaleDateString('en-GB')}</span></div>
                                <div className="info-item"><strong>Student Name</strong> <span>{f.studentName}</span></div>
                                <div className="info-item"><strong>Father Name</strong> <span>{f.fatherName}</span></div>
                                <div className="info-item"><strong>Student ID</strong> <span>{f.admissionNumber || 'N/A'}</span></div>
                                <div className="info-item"><strong>Session</strong> <span>{f.month} {f.year}</span></div>
                                <div className="info-item"><strong>Program</strong> <span>{f.className}</span></div>
                                <div className="info-item"><strong>Institute ID</strong> <span>{instituteId}</span></div>
                             </div>

                             {/* Table */}
                             <ChallanBill voucher={f} settings={feeSettings} />

                             <div style={{display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginTop: 'auto'}}>
                                <div style={{textAlign: 'center', fontSize: '7pt', width: '120px', borderTop: '0.5pt solid #000', paddingTop: '1mm'}}>Student Signature</div>
                                <div style={{textAlign: 'center', fontSize: '7pt', width: '120px', borderTop: '0.5pt solid #000', paddingTop: '1mm'}}>Cashier Stamp</div>
                             </div>
                           </>
                         ) : (
                           <>
                             <div className="copy-header">INFORMATION</div>
                             <div style={{fontSize: '8pt', whiteSpace: 'pre-line', lineHeight: '1.4'}}>
                                {paymentMethods}
                             </div>

                             <div style={{marginTop: 'auto', borderTop: '1pt solid #eee', paddingTop: '3mm'}}>
                                <div style={{fontSize: '8pt', fontWeight: 700, marginBottom: '2mm'}}>Important Notes:</div>
                                <p style={{fontSize: '7pt', color: '#444', margin: 0}}>{challanNote}</p>
                             </div>

                             <div style={{textAlign: 'center', marginTop: '5mm'}}>
                                {/* eslint-disable-next-line @next/next/no-img-element -- logo is a data URL saved in this browser; next/image can't optimise it */}
                                {logo && <img src={logo} alt="Logo" style={{width: '80px', height: '80px', objectFit: 'contain', opacity: 0.8}} />}
                                <div style={{fontSize: '9pt', fontWeight: 800, marginTop: '2mm'}}>{schoolName}</div>
                                <div style={{fontSize: '7pt'}}>{schoolAddress}</div>
                             </div>
                           </>
                         )}
                      </div>
                    </div>
                  ))}
                </div>
              );
            })}
          </div>
        </>
      )}
    </div>
  );
}

"use client";
import React, { useState, useEffect, useRef } from 'react';
import Link from 'next/link';
import './collection.css';
import { useStoredSetting } from '@/lib/useStoredSetting';
import { periodLabel, periodOf, tuitionOf } from '@/lib/fees';
import { useFeeSettings } from '@/lib/useFeeSettings';
import { useFeatures } from '@/lib/useFeatures';
import { receiptMessage, whatsappLink } from '@/lib/whatsapp';
import { VoucherCharges } from '../components/ChargesEditor';
import type { Allocation, FeeVoucher, RecordId } from '@/lib/types';

/** A voucher as shown here; right after a payment it also carries that payment's receipt. */
type ShownVoucher = FeeVoucher & {
  receiptNo?: RecordId;
  receivedBy?: string;
  receivedNow?: number;
  allocations?: Allocation[];
  /** Tuition already paid on this voucher before the payment being taken now. */
  paidEarlier?: number;
};

/** Tuition owed now, arrears and late fines included (annual charges are taken separately). */
const tuitionDue = (v: FeeVoucher) => Math.max(0, (v.balanceDue ?? 0) - (v.remainingAnnualCharges ?? 0));

/** Late fines a payment today would charge (or could waive) on this voucher and its arrears. */
const pendingFine = (v: FeeVoucher) =>
  (v.fineCharged ? 0 : v.lateFine ?? 0) + (v.arrears ?? []).reduce((sum, line) => sum + (line.fine ?? 0), 0);

const rs = (amount: number) => `Rs. ${amount.toLocaleString('en-US')}`;

/** "November 2026 Rs. 3,000 · December 2026 Rs. 3,000 (advance)" */
const appliedTo = (allocations: Allocation[]) =>
  allocations.filter((a) => a.amount > 0).map((a) => `${periodLabel(a)} ${rs(a.amount)}${a.created ? ' (advance)' : ''}`).join(' · ');

export default function FeeCollection() {
  const [search, setSearch] = useState('');
  const [feeData, setFeeData] = useState<ShownVoucher | null>(null);
  const [suggestions, setSuggestions] = useState<FeeVoucher[]>([]);
  const [showDropdown, setShowDropdown] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const [loading, setLoading] = useState(false);
  const [processing, setProcessing] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');

  const [paidTuition, setPaidTuition] = useState<string>('');
  const [paidAC, setPaidAC] = useState<string>('0');
  const [waiveFine, setWaiveFine] = useState(false);
  // Tuition beyond what is owed is kept as advance fee only when the cashier says so.
  const [advance, setAdvance] = useState(false);
  const [takingAdvance, setTakingAdvance] = useState(false);
  const [editingCharges, setEditingCharges] = useState(false);
  const { settings: feeSettings } = useFeeSettings();
  const { has } = useFeatures();

  const [schoolName, saveSchoolName] = useStoredSetting('fms-school-name', 'TRUST SCHOOL SYSTEM');
  const [schoolAddress, saveSchoolAddress] = useStoredSetting('fms-school-address', 'Campus Address / Contact No');
  const [logo] = useStoredSetting('fms-school-logo', '');

  // Pre-fetch all fees for rapid typeahead searching
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setShowDropdown(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);

    // Inject dynamic @page style for A4 portrait
    const styleEl = document.createElement('style');
    styleEl.id = 'print-page-style';
    styleEl.innerHTML = `@media print { @page { size: A4 portrait !important; margin: 8mm !important; } }`;
    document.head.appendChild(styleEl);

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      const el = document.getElementById('print-page-style');
      if (el) el.remove();
    };
  }, []);

  const handleSaveName = (e: React.FocusEvent<HTMLHeadingElement>) => {
    saveSchoolName(e.currentTarget.textContent || 'TRUST SCHOOL SYSTEM');
  };

  const handleSaveAddress = (e: React.FocusEvent<HTMLParagraphElement>) => {
    saveSchoolAddress(e.currentTarget.textContent || 'Campus Address / Contact No');
  };

  const handleSearchChange = async (val: string) => {
    setSearch(val);
    setFeeData(null);
    setErrorMsg('');

    if (val.trim().length > 1) {
      try {
        const res = await fetch(`/api/fees?search=${encodeURIComponent(val)}&limit=8`);
        if (res.ok) {
          const data = await res.json();
          setSuggestions(Array.isArray(data) ? data : []);
          setShowDropdown(true);
        }
      } catch (err) {
        console.error("Suggestion error:", err);
      }
    } else {
      setShowDropdown(false);
    }
  };

  /** Shows a voucher with the full amount owed filled in, ready to take. */
  const openVoucher = (voucher: FeeVoucher) => {
    setFeeData({ ...voucher, paidEarlier: voucher.paidTuition || 0 });
    setPaidTuition(String(tuitionDue(voucher)));
    setPaidAC(String(voucher.remainingAnnualCharges || 0));
    setWaiveFine(false);
    setAdvance(false);
    setTakingAdvance(false);
    setEditingCharges(false);
  };

  const toggleWaiveFine = (waive: boolean) => {
    if (!feeData) return;
    setWaiveFine(waive);
    setPaidTuition(String(Math.max(0, tuitionDue(feeData) - (waive ? pendingFine(feeData) : 0))));
  };

  const selectStudent = (studentFee: FeeVoucher) => {
    setSearch(studentFee.id.toString());
    openVoucher(studentFee);
    setShowDropdown(false);
    setErrorMsg('');
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!search) return;
    setLoading(true);
    setErrorMsg('');
    setFeeData(null);
    try {
      // 1. Search by ID first (Direct API call)
      if (!isNaN(Number(search))) {
        const res = await fetch(`/api/fees?id=${search}`);
        if (res.ok) {
          const data = await res.json();
          const list = Array.isArray(data) ? data : (data.id ? [data] : []);
          if (list.length > 0) {
             openVoucher(list[0]);
             setLoading(false);
             return;
          }
        }
      }

      // 2. Search by Name (API call with search param)
      const res = await fetch(`/api/fees?search=${encodeURIComponent(search)}`);
      if (res.ok) {
        const data = await res.json();
        const results = Array.isArray(data) ? data : [];
        if (results.length > 0) {
          openVoucher(results[0]);
        } else {
          setErrorMsg("No active billing voucher found.");
        }
      } else {
        setErrorMsg("Search failed. Please check connection.");
      }
    } catch (error) {
      console.error("Search error:", error);
      setErrorMsg(`Search failed: ${(error instanceof Error && error.message) || 'Check your internet or server'}`);
    } finally {
      setLoading(false);
    }
  };

  const handlePay = async () => {
    if (!feeData) return;
    setProcessing(true);
    try {
      const res = await fetch('/api/fees', {
        method: 'PUT',
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          id: feeData.id,
          paidTuition: parseFloat(paidTuition) || 0,
          paidAC: parseFloat(paidAC) || 0,
          waiveFine,
          advance
        })
      });
      const updated = await res.json();
      if (res.ok) {
        // The server sends the voucher back with fresh balances and the receipt. The printed receipt
        // still lists the arrears and annual charges as they stood, since this payment covered them.
        const waivedArrearsFines = waiveFine ? (feeData.arrears ?? []).reduce((sum, line) => sum + (line.fine ?? 0), 0) : 0;
        setFeeData({
          ...updated,
          previousArrears: (feeData.previousArrears ?? 0) - waivedArrearsFines,
          arrears: feeData.arrears,
          remainingAnnualCharges: feeData.remainingAnnualCharges,
          paidEarlier: feeData.paidEarlier,
          receivedNow: (parseFloat(paidTuition) || 0) + (parseFloat(paidAC) || 0)
        });
        setTakingAdvance(false);
        setAdvance(false);

        // trigger print wrapper
        setTimeout(() => window.print(), 300);
      } else {
        alert(updated.error);
      }
    } catch {
      alert("Error processing payment.");
    } finally {
      setProcessing(false);
    }
  };

  return (
    <div style={{animation: 'fadeIn 0.5s ease-out'}}>
      <h1 className="no-print">Fee Collection Portal</h1>
      <p className="no-print" style={{marginBottom: '2rem'}}>Scan or enter voucher number / student roll number to receive cash.</p>

      <form onSubmit={handleSearch} className="glass-panel no-print" style={{padding: '2rem', display: 'flex', gap: '1rem', alignItems: 'flex-end', marginBottom: '2rem', position: 'relative'}}>
        <div style={{flex: 1, position: 'relative'}} ref={dropdownRef}>
          <label className="form-label">Search by Name, Father&apos;s Name, or Voucher ID</label>
          <input
            type="text"
            className="form-input"
            placeholder="Start typing name or father's name..."
            value={search}
            onChange={(e) => handleSearchChange(e.target.value)}
            onFocus={() => { if(suggestions.length > 0) setShowDropdown(true); }}
            style={{fontSize: '1.2rem', padding: '1rem'}}
            autoFocus
            autoComplete="off"
          />

          {showDropdown && suggestions.length > 0 && (
            <ul style={{
              position: 'absolute', top: '100%', left: 0, right: 0, marginTop: '0.25rem',
              background: 'var(--bg-card)', border: '1px solid var(--border)',
              borderRadius: '8px', boxShadow: 'var(--shadow-card)',
              maxHeight: '300px', overflowY: 'auto', zIndex: 100, listStyle: 'none', margin: '0.25rem 0 0 0', padding: 0
            }}>
              {suggestions.map(s => (
                <li
                  key={s.id}
                  onClick={() => selectStudent(s)}
                  className="dropdown-item"
                  style={{padding: '0.8rem 1rem', borderBottom: '1px solid var(--border)', cursor: 'pointer', display: 'flex', justifyContent: 'space-between', alignItems: 'center'}}
                >
                  <div>
                    <strong style={{color: 'var(--text-main)', fontSize: '1.05rem'}}>{s.studentName}</strong>
                    <div style={{fontSize: '0.85rem', color: 'var(--text-muted)'}}>S/O: {s.fatherName}</div>
                    <div style={{fontSize: '0.8rem', color: 'var(--text-muted)'}}>Cycle: {s.month} {s.year}</div>
                  </div>
                  <div style={{textAlign: 'right'}}>
                    <span className={`badge ${s.status === 'Paid' ? 'badge-success' : 'badge-warning'}`}>{s.status}</span>
                    <div style={{fontSize: '0.85rem', fontWeight: 600, color: 'var(--text-main)'}}>Class: {s.className}</div>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </div>
        <div>
          <button type="submit" className="btn btn-primary" style={{height: '52px', padding: '0 2.5rem'}}>
            {loading ? 'Searching...' : 'Find Record'}
          </button>
        </div>
      </form>

      {errorMsg && (
        <div className="badge badge-danger no-print" style={{padding: '1rem', display: 'block', fontSize: '1rem', marginBottom: '2rem'}}>
          {errorMsg}
        </div>
      )}

      {feeData && (
        <div className="receipt-container" style={{maxWidth: '800px', margin: '0 auto'}}>
          <div className="physical-receipt">
            {/* eslint-disable-next-line @next/next/no-img-element -- logo is a data URL saved in this browser; next/image can't optimise it */}
            {logo && <img src={logo} alt="Watermark" style={{
                position: 'absolute',
                top: '50%',
                left: '50%',
                transform: 'translate(-50%, -50%)',
                width: '70%',
                opacity: 0.08,
                zIndex: 0,
                pointerEvents: 'none'
            }} />}
            {/* Header Section */}
            <div className="receipt-header-main" contentEditable suppressContentEditableWarning onBlur={handleSaveName}>
              {schoolName === 'TRUST SCHOOL SYSTEM' ? "THE BROOK FIELD SCHOOL'S SYSTEM" : schoolName}
            </div>

            <div className="campus-grid">
              <div className="campus-item" contentEditable suppressContentEditableWarning>
                BOYS CAMPUS<br/>Allama Iqbal Colony
              </div>
              <div className="campus-item" contentEditable suppressContentEditableWarning>
                BENCHMARK CAMPUS<br/>DHOKE MANGTAL
              </div>
            </div>

            <div className="contact-header-bar" contentEditable suppressContentEditableWarning onBlur={handleSaveAddress}>
              {schoolAddress === 'Campus Address / Contact No' ? "Dhoke Hassu, Rawalpindi. Mob: 0333-5435678, 0345-5904708" : schoolAddress}
            </div>

            {/* Sub Header (Official Receipt + ID) */}
            <div style={{display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px'}}>
               <div style={{display: 'flex', gap: '10px', alignItems: 'center'}}>
                  <span style={{fontWeight: 800}}>Dated:</span>
                  <span style={{borderBottom: '1px solid #1e3a8a', minWidth: '150px', fontWeight: 600}} contentEditable suppressContentEditableWarning>{new Date().toLocaleDateString()}</span>
               </div>
               <div style={{textAlign: 'center'}}>
                  <span style={{background: '#3730a3', color: 'white', padding: '2px 15px', borderRadius: '4px', fontWeight: 900, fontSize: '0.8rem'}}>OFFICIAL RECEIPT</span>
               </div>
               <div style={{display: 'flex', gap: '10px', alignItems: 'center'}}>
                  <span style={{fontWeight: 800}}>{feeData.receiptNo ? 'Receipt No.' : 'Voucher No.'}</span>
                  <span style={{fontSize: '1.5rem', fontWeight: 900, letterSpacing: '2px'}}>{feeData.receiptNo ?? feeData.id}</span>
               </div>
            </div>

            {/* Student Info Lines */}
            <div className="info-row">
              <span className="info-label">Name</span>
              <span className="info-value" contentEditable suppressContentEditableWarning>{feeData.studentName}</span>
            </div>
            <div style={{display: 'flex', gap: '20px'}}>
              <div className="info-row" style={{flex: 2}}>
                <span className="info-label">S/O</span>
                <span className="info-value" contentEditable suppressContentEditableWarning>{feeData.fatherName}</span>
              </div>
              <div className="info-row" style={{flex: 1}}>
                <span className="info-label">Class</span>
                <span className="info-value" contentEditable suppressContentEditableWarning>{feeData.className}</span>
              </div>
            </div>

            {/* Particulars Table */}
            <table className="particulars-table">
              <thead>
                <tr>
                  <th style={{width: '70%'}}>PARTICULAR</th>
                  <th>AMOUNT</th>
                </tr>
              </thead>
              <tbody>
                {(() => {
                  // Numbered as printed; the cashier can still retype a cell before printing.
                  const success = {color: 'var(--success)', fontWeight: 'bold'} as const;
                  const lines: { label: React.ReactNode; amount: React.ReactNode; style?: React.CSSProperties; amountStyle?: React.CSSProperties; numbered?: false }[] = [
                    { label: `Tuition Fee (Month: ${feeData.month})`, amount: tuitionOf(feeData) },
                    ...((feeData.discount ?? 0) > 0 ? [{ label: 'Scholarship / Discount', amount: `- ${feeData.discount}`, style: success }] : []),
                    ...(feeData.charges ?? []).map((c) => ({ label: c.label, amount: c.amount })),
                    ...((feeData.paidEarlier ?? 0) > 0
                      ? [{ label: 'Less: Paid Earlier on This Voucher', amount: `- ${feeData.paidEarlier}`, style: {color: 'var(--success)'}, numbered: false as const }]
                      : []),
                    {
                      label: (
                        <>
                          Previous Balance / Arrears
                          {(feeData.arrears ?? []).length > 0 && (
                            <span style={{fontSize: '0.8em', color: '#64748b'}}> ({(feeData.arrears ?? []).map((line) => periodLabel(line)).join(', ')})</span>
                          )}
                        </>
                      ),
                      amount: feeData.previousArrears || 0,
                    },
                    {
                      label: 'Annual Charges (AC) Pending',
                      amount: feeData.remainingAnnualCharges || 0,
                      amountStyle: {color: (feeData.remainingAnnualCharges ?? 0) > 0 ? 'var(--danger)' : 'inherit'},
                    },
                    { label: `Late Fine${feeData.fineWaived ? ' (waived)' : ''}`, amount: feeData.lateFine || 0 },
                  ];
                  let no = 0;
                  return lines.map((line, i) =>
                    line.numbered === false ? (
                      <tr key={i}>
                        <td style={line.style}>{line.label}</td>
                        <td style={{textAlign: 'right', ...line.style}}>{line.amount}</td>
                      </tr>
                    ) : (
                      <tr key={i}>
                        <td style={line.style} contentEditable suppressContentEditableWarning>{++no}. {line.label}</td>
                        <td style={{textAlign: 'right', ...line.style, ...line.amountStyle}} contentEditable suppressContentEditableWarning>{line.amount}</td>
                      </tr>
                    )
                  );
                })()}
              </tbody>
            </table>



            {/* Calculation & Signatures */}
            <div style={{display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start'}}>
              <div style={{flex: 1}}>
                 <div className="signature-section" style={{marginTop: '20px'}}>
                    <div className="sig-item" contentEditable suppressContentEditableWarning>Accountant</div>
                    <div className="sig-item" contentEditable suppressContentEditableWarning>Sig./Stamp</div>
                 </div>
                 <div className="no-print" style={{marginTop: '30px', textAlign: 'center'}}>
                    {feeData.status === 'Paid' || feeData.status === 'Partially Paid' || feeData.receiptNo ? (
                       <p style={{color: 'var(--success)', fontWeight: 'bold'}}>
                         {feeData.receiptNo
                           ? `✓ Receipt #${feeData.receiptNo} issued by ${feeData.receivedBy} (voucher #${feeData.id})`
                           : `✓ Payment recorded${feeData.paymentDate ? ` on ${new Date(feeData.paymentDate).toLocaleDateString()}` : ''}`}
                       </p>
                    ) : null}
                    <button className="btn btn-secondary" onClick={() => window.print()} style={{marginTop: '10px'}}>Print Receipt</button>
                    {feeData.studentId != null && has('studentLedger') && (
                      <Link href={`/ledger/${feeData.studentId}`} className="btn btn-secondary" style={{marginTop: '10px', marginLeft: '0.5rem'}}>Student Ledger</Link>
                    )}
                    {(() => {
                      if (!feeData.receiptNo || !has('whatsapp')) return null;
                      const months = (feeData.allocations ?? []).filter((a) => a.amount > 0).map((a) => periodLabel(a)).join(', ');
                      const link = whatsappLink(feeData.parentPhone, receiptMessage({
                        school: feeSettings.schoolName || 'the school',
                        student: feeData.studentName ?? 'your child',
                        amount: feeData.receivedNow ?? 0,
                        receiptNo: feeData.receiptNo,
                        months,
                        balance: feeData.balanceDue ?? 0
                      }));
                      return link ? (
                        <a href={link} target="_blank" rel="noopener noreferrer" className="btn" style={{marginTop: '10px', marginLeft: '0.5rem', background: '#25D366', color: 'white', border: 'none'}}>Send on WhatsApp</a>
                      ) : null;
                    })()}
                 </div>
              </div>

              {(() => {
                // Before saving, "received" previews the amounts typed in; afterwards it is the receipt.
                // Money for months after this one (advance fee) is shown apart from what was owed.
                const received = feeData.receivedNow ?? ((parseFloat(paidTuition) || 0) + (parseFloat(paidAC) || 0));
                const owedNow = (feeData.balanceDue ?? 0) - (waiveFine && !feeData.receiptNo ? pendingFine(feeData) : 0);
                const ahead = feeData.receiptNo
                  ? (feeData.allocations ?? []).filter((a) => periodOf(a) > periodOf(feeData)).reduce((sum, a) => sum + a.amount, 0)
                  : Math.max(0, received - owedNow);
                const payable = feeData.receiptNo ? owedNow + received - ahead : owedNow;
                return (
                  <div className="calculation-box">
                    <div className="calc-row">
                      <div className="calc-label">Total Payable</div>
                      <div className="calc-value">{payable}</div>
                    </div>
                    <div className="calc-row">
                      <div className="calc-label">{feeData.receiptNo ? 'Received' : 'Receiving'}</div>
                      <div className="calc-value">{received}</div>
                    </div>
                    {ahead > 0 && (
                      <div className="calc-row">
                        <div className="calc-label">Advance (coming months)</div>
                        <div className="calc-value">{ahead}</div>
                      </div>
                    )}
                    <div className="calc-row balance-row">
                      <div className="calc-label">Pending / Bal.</div>
                      <div className="calc-value">{Math.max(0, payable - received + ahead)}</div>
                    </div>
                  </div>
                );
              })()}



            </div>

            {(feeData.allocations ?? []).length > 0 && (
              <p style={{fontSize: '0.85rem', marginTop: '1rem'}}>
                <strong>Applied to: </strong>
                {appliedTo(feeData.allocations ?? [])}
                {(feeData.allocations ?? []).some((a) => a.fineWaived) ? ' · late fine waived' : ''}
              </p>
            )}

            {/* Charges on this voucher (No Print): admission fee, exam fee... */}
            {!feeData.receiptNo && has('charges') && (
              <div className="no-print" style={{marginTop: '1.5rem'}}>
                {editingCharges ? (
                  <div style={{border: '1px solid #ccc', borderRadius: '8px', padding: '1rem'}}>
                    <p style={{fontWeight: 700, marginBottom: '0.75rem'}}>Charges on this voucher (on top of the monthly fee)</p>
                    <VoucherCharges voucher={feeData} onSaved={openVoucher} onCancel={() => setEditingCharges(false)} />
                  </div>
                ) : (
                  <button className="btn btn-secondary" onClick={() => setEditingCharges(true)}>
                    {(feeData.charges ?? []).length > 0 ? 'Edit charges' : '+ Add admission / exam / other charge'}
                  </button>
                )}
              </div>
            )}

            {(feeData.balanceDue ?? 0) <= 0 && !takingAdvance && feeData.studentId != null && has('advance') && (
              <div className="no-print" style={{marginTop: '1rem'}}>
                <button className="btn btn-secondary" onClick={() => { setTakingAdvance(true); setAdvance(true); setPaidTuition(''); setPaidAC('0'); }}>
                  Receive advance fee for coming months
                </button>
              </div>
            )}

            {/* Payment Controls (No Print) */}
            {((feeData.balanceDue ?? 0) > 0 || takingAdvance) && (
               <div className="no-print" style={{marginTop: '2rem', borderTop: '1px solid #ccc', paddingTop: '1rem'}}>
                  {(feeData.arrears ?? []).length > 0 && (
                    <p style={{fontSize: '0.9rem', marginBottom: '0.75rem'}}>
                      Earlier months still owing (cleared first):{' '}
                      {(feeData.arrears ?? []).map((line) => `${periodLabel(line)} ${rs(line.amount)}${line.fine ? ` incl. ${rs(line.fine)} fine` : ''}`).join(' · ')}
                    </p>
                  )}
                  {pendingFine(feeData) > 0 && (
                    <label style={{display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.75rem', color: 'var(--danger)', fontWeight: 600}}>
                      <input type="checkbox" checked={waiveFine} onChange={(e) => toggleWaiveFine(e.target.checked)} />
                      Waive late fine of {rs(pendingFine(feeData))} (recorded in the Activity Log)
                    </label>
                  )}
                  {(() => {
                    const extra = (parseFloat(paidTuition) || 0) - Math.max(0, tuitionDue(feeData) - (waiveFine ? pendingFine(feeData) : 0));
                    if (extra <= 0 || !has('advance')) return null;
                    return (
                      <label style={{display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.75rem', fontWeight: 600}}>
                        <input type="checkbox" checked={advance} onChange={(e) => setAdvance(e.target.checked)} />
                        Advance fee: keep the extra {rs(extra)} for the coming months (their vouchers are made now and marked paid)
                      </label>
                    );
                  })()}
                  <div style={{display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem', marginBottom: '1rem'}}>
                     <div>
                        <label className="form-label">Receive Tuition &amp; Charges</label>
                        <input type="number" className="form-input" value={paidTuition} onChange={e => setPaidTuition(e.target.value)} />
                     </div>
                     <div>
                        <label className="form-label">Receive AC/Misc</label>
                        <input type="number" className="form-input" value={paidAC} onChange={e => setPaidAC(e.target.value)} />
                     </div>
                  </div>
                  <button className="btn btn-primary" onClick={handlePay} disabled={processing} style={{width: '100%'}}>
                    {processing ? 'Processing...' : 'Confirm & Save Payment'}
                  </button>
               </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

